import { useState, useEffect } from 'react';
import { Outlet, useNavigate, Link, Routes, Route } from 'react-router-dom'; // 👈 Add Routes, Route
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

// Import your admin pages
import Home from './Home';
import Students from './Students';
import Courses from './Courses';
import Questions from './Questions';

const styles = {
  container: {
    background: '#f6f7fa',
    minHeight: '100vh'
  },
  sidebar: {
    background: '#0e1a35',
    height: '100vh',
    position: 'fixed',
    width: '250px'
  },
  logo: {
    textAlign: 'center',
    padding: '16px 0'
  },
  logoImg: {
    maxWidth: '180px',
    width: '100%'
  },
  navItem: {
    borderBottom: '1px solid #0d172e',
    borderTop: '1px solid #0d172e',
    color: '#ffffff',
    display: 'block',
    fontSize: '17px',
    fontWeight: '500',
    padding: '28px 20px',
    textDecoration: 'none'
  },
  navItemActive: {
    background: '#122143',
    borderLeft: '5px solid #5584ff',
    paddingLeft: '15px'
  },
  navIcon: {
    marginRight: '15px',
    color: '#5584ff'
  },
  mainContent: {
    marginLeft: '250px',
    padding: '20px'
  },
  header: {
    background: '#ffffff',
    boxShadow: '0 1px 12px rgba(0,0,0,0.04)',
    padding: '15px',
    marginBottom: '20px'
  }
};

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('dashboard');

  // Set active tab based on URL
  useEffect(() => {
    const path = window.location.pathname;
    if (path === '/admin') setActiveTab('dashboard');
    else if (path === '/admin/students') setActiveTab('students');
    else if (path === '/admin/courses') setActiveTab('courses');
    else if (path === '/admin/questions') setActiveTab('questions');
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  return (
    <div style={styles.container}>
      {/* Sidebar */}
      <div style={styles.sidebar}>
        <div style={styles.logo}>
          <img 
            src="https://cdn-icons-png.flaticon.com/512/2972/2972185.png" 
            alt="Quiz Logo" 
            style={styles.logoImg}
          />
        </div>
        <div className="navi">
          <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
            {[
              { id: 'dashboard', label: 'Home', icon: 'fa-home', path: '/admin' },
              { id: 'students', label: 'Students', icon: 'fa-user', path: '/admin/students' },
              { id: 'courses', label: 'Courses', icon: 'fa-book', path: '/admin/courses' },
              { id: 'questions', label: 'Questions', icon: 'fa-question', path: '/admin/questions' }
            ].map(item => (
              <li key={item.id}>
                <Link 
                  to={item.path}
                  onClick={() => setActiveTab(item.id)}
                  style={{
                    ...styles.navItem,
                    ...(activeTab === item.id ? styles.navItemActive : {})
                  }}
                >
                  <i className={`fa ${item.icon}`} style={styles.navIcon}></i>
                  <span>{item.label}</span>
                </Link>
              </li>
            ))}
          </ul>
        </div>
      </div>

      {/* Main Content */}
      <div style={styles.mainContent}>
        <header style={styles.header}>
          <div className="d-flex justify-content-between align-items-center">
            <h1>Admin Dashboard</h1>
            <button 
              onClick={handleLogout}
              className="btn btn-danger btn-sm"
            >
              Logout
            </button>
          </div>
        </header>

        {/* 👇 THIS IS THE KEY CHANGE */}
        <Routes>
          <Route index element={<Home />} />
          <Route path="students" element={<Students />} />
          <Route path="courses" element={<Courses />} />
          <Route path="questions" element={<Questions />} />
        </Routes>
      </div>
    </div>
  );
}
